const arasInstance = window.aras;
const state = options.getState();
const shouldSearchDialogEventBeInvoked = window.searchContainer._onSearchDialogEventMustBeInvoked();

const searchModes = {};
const searchModesItems = arasInstance.getSearchModes() || [];
searchModesItems.forEach((searchMode) => {
	const name = arasInstance.getItemProperty(searchMode, 'name');
	const label = arasInstance.getItemProperty(searchMode, 'label') || name;
	const value = arasInstance.getItemProperty(searchMode, 'id');
	searchModes[name] = {name, label, value};
});

const mode = state.searching.mode;
const modeId = searchModes[mode]?.value;

const initProperties = {
	value: modeId,
	disabled: state.redlineView || shouldSearchDialogEventBeInvoked
};

if (!target.options || !target.options.length) {
	initProperties.options = Object.values(searchModes);
}

return initProperties;
